import{_ as a,o,c as t,ag as i}from"./chunks/framework.BwSLX4ak.js";const p=JSON.parse('{"title":"Production security checklist","description":"","frontmatter":{},"headers":[],"relativePath":"en/shitbot/security.md","filePath":"en/shitbot/security.md"}'),s={name:"en/shitbot/security.md"};function r(n,e,l,d,c,u){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="production-security-checklist" tabindex="-1">Production security checklist <a class="header-anchor" href="#production-security-checklist" aria-label="Permalink to &quot;Production security checklist&quot;">​</a></h1><h2 id="onebot" tabindex="-1">OneBot <a class="header-anchor" href="#onebot" aria-label="Permalink to &quot;OneBot&quot;">​</a></h2><ul><li>Set a nonempty, unguessable access token in production.</li><li>Restrict <code>allowed-group-ids</code>; avoid <code>allow-all-groups: true</code>.</li><li>Use <code>ws://127.0.0.1</code> on the same host.</li><li>Use <code>wss://</code> between hosts.</li><li>Consider <code>allow-insecure-remote-websocket</code> only inside a trusted encrypted tunnel.</li><li>Restrict access to the OneBot port with a firewall.</li><li>Do not expose tokens in logs, screenshots, or issues.</li></ul><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><ul><li>Create a dedicated ShitBot database account.</li><li>Grant only required permissions on the target database.</li><li>Use <code>sslMode=VERIFY_IDENTITY</code> for remote MySQL.</li><li>Keep <code>allowPublicKeyRetrieval=false</code>.</li><li>Never share SQLite files between processes.</li><li>Back up before upgrades, migrations, or platform changes.</li><li>Do not expose database URLs, usernames, or passwords.</li></ul><h2 id="proxy-backend-channel" tabindex="-1">Proxy/backend channel <a class="header-anchor" href="#proxy-backend-channel" aria-label="Permalink to &quot;Proxy/backend channel&quot;">​</a></h2><ul><li>Use a different random token of at least 16 characters for each backend.</li><li>Bind same-host listeners to <code>127.0.0.1</code>.</li><li>Enable TLS between machines.</li><li>Put only actual proxy IPs in <code>allowed-proxy-addresses</code>.</li><li>Allow only the proxy to reach the listener port through the firewall.</li><li>Do not expose the listener directly to the Internet.</li><li>Keep the HMAC token even with TLS.</li><li>Enable mutual TLS when stronger identity verification is needed.</li></ul><p>HMAC provides request authentication and integrity, not encryption. Protect cross-machine traffic with TLS or a trusted encrypted tunnel.</p><h2 id="qq-shortcuts" tabindex="-1">QQ shortcuts <a class="header-anchor" href="#qq-shortcuts" aria-label="Permalink to &quot;QQ shortcuts&quot;">​</a></h2><ul><li>Configure only console commands that are actually needed.</li><li>Set <code>permission</code> for sensitive shortcuts.</li><li>Keep <code>allow-unbound: false</code>.</li><li>Restrict groups and command aliases.</li><li>Do not concatenate arbitrary group input into unrestricted console commands.</li><li>Review LuckPerms, Vault, and OP permissions regularly.</li><li>Monitor cooldowns, timeouts, and queues against actual load.</li></ul><p>An empty <code>permission</code> only skips the game permission check. <code>allow-unbound: true</code> permits unbound members to call the command, so reassess its risk before enabling it.</p><h2 id="advanced-image-templates" tabindex="-1">Advanced image templates <a class="header-anchor" href="#advanced-image-templates" aria-label="Permalink to &quot;Advanced image templates&quot;">​</a></h2><ul><li>Keep <code>custom-image-templates.enabled: false</code> if unnecessary; no renderer is downloaded or loaded.</li><li>Use the matching official <code>ShitBotRenderer</code>, <code>.sha256</code>, and <code>.sig</code>; do not bypass signatures.</li><li>Keep the editor on loopback. For remote access, use an HTTPS reverse proxy, preserve the original <code>Host</code>, and do not expose the internal port.</li><li>Treat <code>/shitbot editor</code> URLs as short-lived, one-time credentials; do not share them in group chats, logs, or issues.</li><li>Remote images are enabled by default for avatars but remain subject to HTTPS, address, and resource limits. Disable <code>custom-image-templates.remote-images.enabled</code> if network images are unnecessary.</li><li>Do not edit <code>versions/</code> or <code>published.yml</code> manually. Production rendering should use published snapshots.</li><li>Do not raise canvas, pixel, layer, loop, asset, timeout, thread, or queue limits without bounds.</li><li>Custom providers must switch to the correct thread before accessing platform APIs and return only needed rendering data.</li></ul><p>The template engine does not execute uploaded HTML, JavaScript, or arbitrary server commands and contains no browser engine. Image commands and console shortcuts in <code>commands.yml</code> are separate mechanisms.</p><h2 id="account-binding" tabindex="-1">Account binding <a class="header-anchor" href="#account-binding" aria-label="Permalink to &quot;Account binding&quot;">​</a></h2><ul><li>Keep verification-code expiry and attempt limits.</li><li>Do not reduce <code>code-alphabet</code> to a very small character set.</li><li>Set <code>maximum-ids-per-qq</code> to match your server policy.</li><li>Confirm that leaving a group should remove bindings before enabling <code>group-leave-unbind</code>.</li><li>Do not bypass binding checks when the database fails.</li><li>Move EasyBot database copies out after migration.</li></ul><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><ul><li>Download JARs only from official GitHub releases.</li><li>Preserve the <code>.sha256</code> and <code>.sig</code> verification chain.</li><li>Investigate update failures instead of bypassing signatures.</li><li>Update proxies and backends together.</li><li>Restart normally after replacing a JAR; do not hot-load with a plugin manager.</li><li>Store the release private key only in repository secrets.</li></ul><h2 id="logs-and-backups" tabindex="-1">Logs and backups <a class="header-anchor" href="#logs-and-backups" aria-label="Permalink to &quot;Logs and backups&quot;">​</a></h2><ul><li>Remove tokens, passwords, database addresses, and private player data before sharing logs.</li><li>QQ shortcut log redaction supplements, rather than replaces, least privilege.</li><li>Encrypt database backups and restrict access.</li><li>Configuration backups also contain sensitive information.</li><li>Do not commit production configuration, databases, or signing private keys to Git.</li><li>Regularly confirm that backups can be restored.</li></ul><h2 id="network-and-resources" tabindex="-1">Network and resources <a class="header-anchor" href="#network-and-resources" aria-label="Permalink to &quot;Network and resources&quot;">​</a></h2><ul><li>Restrict sources allowed to reach database, OneBot, backend listener, and management ports.</li><li>Set connection and read timeouts for remote services.</li><li>Keep database, rendering, provider, and command queues bounded.</li><li>Use trusted sources for inventory resource packs and client JARs.</li><li>Use HTTPS for avatars and external images.</li></ul>',22)])])}const m=a(s,[["render",r]]);export{p as __pageData,m as default};
